if (args.Length < 2) { Console.Error.WriteLine("Usage: Emuera.Next.VmAudit <fixture-root> <report-directory> [legacy-manifest.jsonl] [phase1-compiler-manifest.jsonl]"); return 2; }
var auditWatch = Stopwatch.StartNew(); var fixtureRoot = Path.GetFullPath(args[0]);
var erbRoot = Directory.Exists(Path.Combine(fixtureRoot, "Data", "ERB")) ? Path.Combine(fixtureRoot, "Data", "ERB") : fixtureRoot;
var report = Path.GetFullPath(args[1]); Directory.CreateDirectory(report); var legacyPath = args.Length > 2 ? Path.GetFullPath(args[2]) : null; var phase1Path = args.Length > 3 ? Path.GetFullPath(args[3]) : null;
