var sourceRows = files.SelectMany((file, fileOrdinal) => file.Functions.Select((function, functionOrdinal) => new SourceRow(NormalizeRelative(Path.GetRelativePath(erbRoot, file.FileIdentity)), functionOrdinal, function.Span.StartLine, function.Name, fileOrdinal, function.Flags))).ToArray();
var sourceKeys = sourceRows.Select(x => new SemanticFunctionKey(x.RelativeFile, x.FunctionOrdinal)).ToHashSet(); var legacyByKey = legacy.Rows.ToDictionary(x => new SemanticFunctionKey(x.RelativeFile, x.FunctionOrdinal));
var identityMissingRows = sourceRows.Where(x => !legacyByKey.ContainsKey(new(x.RelativeFile, x.FunctionOrdinal))).ToArray(); var identityExtraRows = legacy.Rows.Where(x => !sourceKeys.Contains(new(x.RelativeFile, x.FunctionOrdinal))).ToArray();
var sourcePositionKeys = sourceRows.Select(x => $"{x.RelativeFile}:{x.StartLine}").ToHashSet(StringComparer.OrdinalIgnoreCase); var sourceByOrdinal = sourceRows.ToDictionary(x => new SemanticFunctionKey(x.RelativeFile, x.FunctionOrdinal));
var positionResidualRows = legacy.Rows.Where(x => !sourcePositionKeys.Contains($"{x.RelativeFile}:{x.StartLine}")).Select(x => { var hasSource = sourceByOrdinal.TryGetValue(new(x.RelativeFile, x.FunctionOrdinal), out var source); return new PositionResidual(x.RelativeFile, x.FunctionOrdinal, hasSource ? source.FunctionOrdinal : -1, x.StartLine, hasSource ? source.StartLine : -1, hasSource ? source.PhysicalName : "<no SourceIndex definition>", x.FunctionName); }).ToArray();
var exactPhysicalStartLineMatch = legacy.Rows.Count(x => sourcePositionKeys.Contains($"{x.RelativeFile}:{x.StartLine}"));
