var phase1Keys = phase1Path is null ? null : ReadPhase1Keys(phase1Path); var compiler = new FunctionCompiler(CompilerCompatibilityOptions.LegacyDefaults); var prototypes = new List<FunctionPrototype>(sourceRows.Length); var compiledIds = new List<int>(); var excluded = new List<string>();
var instructionCount = 0; var compileErrors = 0; var phase1Matches = 0; var compileWatch = Stopwatch.StartNew(); var functionId = 0;
foreach (var file in files)
{
