        if (phase1Keys is not null && !phase1Keys.Contains(key)) { excluded.Add($"{key}\t{function.Name}"); continue; } if (phase1Keys is not null) phase1Matches++;
        var read = session.Read(function); if (read.Status != SourceReadStatus.Read) { compileErrors++; continue; } var result = compiler.TryCompile(read.Source!.Value); if (result.Status != CompileStatus.Compiled) { compileErrors++; continue; }
        var compiled = result.Function!; var bytes = read.Source.Value.Bytes; var operands = compiled.Instructions.Select(i => i.OperandLength == 0 ? string.Empty : Encoding.UTF8.GetString(bytes, i.OperandOffset, i.OperandLength)).ToImmutableArray(); prototypes.Add(new(id, compiled.Instructions, operands)); compiledIds.Add(id); instructionCount += compiled.Instructions.Length;
