var effectiveGroups = ids.Where(id => catalog[id].EffectiveNameKnown).GroupBy(id => catalog.GetEffectiveName(id)!, StringComparer.OrdinalIgnoreCase).Where(x => x.Count() > 1).ToArray(); var physicalGroups = ids.GroupBy(catalog.GetPhysicalName, StringComparer.OrdinalIgnoreCase).Where(x => x.Count() > 1).ToArray();
