var maxDepth = link.Program.StructuralLinks.Length == 0 ? 0 : link.Program.StructuralLinks.Max(x => x.Depth); var maxFunctionInstructions = prototypes.Count == 0 ? 0 : prototypes.Max(x => x.Instructions.Length); var instructionPayload = (long)link.Program.Code.Length * Marshal.SizeOf<VmInstruction>(); var descriptorPayload = (long)link.Program.Descriptors.Length * Marshal.SizeOf<VmFunctionDescriptor>(); var recordPayload = (long)link.Program.StructuralLinks.Length * Marshal.SizeOf<StructuralLinkRecord>(); var sidePayload = (long)link.Program.SifLinks.Length * Marshal.SizeOf<SifLinkRecord>() + (long)link.Program.IfGroups.Length * Marshal.SizeOf<IfGroupDescriptor>() + (long)link.Program.IfClauses.Length * Marshal.SizeOf<IfClauseRecord>() + (long)link.Program.SelectGroups.Length * Marshal.SizeOf<SelectGroupDescriptor>() + (long)link.Program.SelectCases.Length * Marshal.SizeOf<SelectCaseRecord>() + (long)link.Program.Loops.Length * Marshal.SizeOf<LoopDescriptor>() + (long)link.Diagnostics.Count * 8 + (long)link.StructuralDiagnostics.Count * 16; var knownLinkedPayload = instructionPayload + descriptorPayload + recordPayload + sidePayload; var catalogKnownPayload = (long)catalog.Count * Marshal.SizeOf<FunctionCatalogEntry>() + (long)catalog.CandidateIdCount * 4 + (long)catalog.NameRangeCount * 8 + (long)catalog.NameTable.Count * 8 + (long)catalog.FileTableCount * 8; var retained = MeasureRetained(files, erbRoot, overlay, prototypes, catalogKnownPayload, knownLinkedPayload);
var fatalDiagnostics = link.StructuralDiagnostics.Count(x => x.Classification == StructuralClassification.InvalidStructure) + link.Diagnostics.Count(x => !x.Contains(" warning=", StringComparison.Ordinal)); var warningDiagnostics = link.StructuralDiagnostics.Count(x => x.Classification == StructuralClassification.ValidWithStructuralWarning); var coreNextPipelineMs = indexWatch.Elapsed.TotalMilliseconds + catalogWatch.Elapsed.TotalMilliseconds + compileWatch.Elapsed.TotalMilliseconds + linkWatch.Elapsed.TotalMilliseconds; var auditResult = compileErrors == 0 && fatalDiagnostics == 0 && spanMismatch == 0 && localPcErrors == 0 && executableReal == 0 && identityMissingRows.Length == 0 && identityExtraRows.Length == 0 && retained.AllValid ? "PASS" : "REVIEW";

Write("function-id-catalog-summary.txt", $"definitions={catalog.Count}\nuniqueFunctionIds={catalog.Count}\nduplicateFunctionIds=0\ndeterministicEnumeration=SourceIndex file order + function ordinal\nphysicalSourceNameDuplicateGroups={physicalGroups.Length}\neffectiveNameDuplicateGroups={effectiveGroups.Length}\neffectiveDuplicateDefinitions={effectiveGroups.Sum(x => x.Count())}\nsemanticOverlayRows={overlay.Count}\nsemanticIdentityJoin={sourceRows.Length - identityMissingRows.Length}/{sourceRows.Length}\nsemanticIdentityJoinMissing={identityMissingRows.Length}\nsemanticIdentityJoinExtra={identityExtraRows.Length}\nexactPhysicalStartLineMatch={exactPhysicalStartLineMatch}\nknownPositionResidual={positionResidualRows.Length}\ncompiledFunctions={prototypes.Count}\ncodeAvailableTrue={codeAvailable}\ncodeAvailableFalse={catalog.Count - codeAvailable}\ncompactEntrySize={catalog.CompactEntrySize}\nnameTableEntries={catalog.NameTable.Count}\nfileTableEntries={catalog.FileTableCount}\ncandidateFunctionIds={catalog.CandidateIdCount}\n");
Write("semantic-overlay-summary.txt", $"manifest={legacyPath ?? "NONE"}\nsourceIndexDefinitions={catalog.Count}\nlegacySemanticRows={legacy.Rows.Length}\noverlayRows={overlay.Count}\nSemanticIdentityJoin={sourceRows.Length - identityMissingRows.Length}/{sourceRows.Length}\nSemanticIdentityJoinMissing={identityMissingRows.Length}\nSemanticIdentityJoinExtra={identityExtraRows.Length}\nExactPhysicalStartLineMatch={exactPhysicalStartLineMatch}\nKnownPositionResidual={positionResidualRows.Length}\nEffectiveNameKnown={ids.Count(id => catalog[id].EffectiveNameKnown)}\nEffectiveNameUnknown={ids.Count(id => !catalog[id].EffectiveNameKnown)}\n");
Write("position-residuals.tsv", "RelativeFile\tLegacyOrdinal\tSourceIndexOrdinal\tLegacyStartLine\tSourceIndexStartLine\tPhysicalName\tEffectiveName\n" + string.Join("\n", positionResidualRows.Select(x => $"{x.RelativeFile}\t{x.LegacyOrdinal}\t{x.SourceIndexOrdinal}\t{x.LegacyStartLine}\t{x.SourceIndexStartLine}\t{x.PhysicalName}\t{x.EffectiveName}")));
