Write("duplicate-summary.txt", $"effectiveNameDuplicateGroups={effectiveGroups.Length}\neffectiveDuplicateDefinitions={effectiveGroups.Sum(x => x.Count())}\nphysicalSourceNameDuplicateGroups={physicalGroups.Length}\nexpectedEffectiveGroups=3\nexpectedEffectiveDefinitions=9\n"); Write("compact-layout.txt", $"FunctionCatalogEntrySize={catalog.CompactEntrySize}\nCatalogEntryFields=CatalogSourceRef(8)+EffectiveNameId(4)+PackedMetadata(4)\nFileTableEntries={catalog.FileTableCount}\nNameTableEntries={catalog.NameTable.Count}\nCandidateFunctionIds={catalog.CandidateIdCount}\nPermanentSourceLookup={catalog.HasPermanentSourceLookup}\nPerFunctionClassObjects=0\nPerNameIntArrays=0\nPermanentCompositePathStrings=0\n"); Write("name-ranges-summary.txt", $"fixedComparer={(catalog.IgnoreCase ? "OrdinalIgnoreCase" : "Ordinal")}\nlookupRebuildPerCall=False\norderedCandidateStream=True\nunknownEffectiveNamesExcluded=True\n"); Write("object-graph-audit.txt", "perFunctionClassObject=0\nperNameIntArrayObject=0\nperFunctionCompositePathString=0\nVmInstructionForbiddenReferences=0\nsideTableForbiddenReferences=0\nrequiredCatalogReferences=SourceIndex+nameTable/nameRanges/candidateFunctionIds\n");
Write("fixed-call-link-summary.txt", $"calls={link.Calls}\njumps={link.Jumps}\nstaticTargetScanSuccess={link.Calls + link.Jumps - link.CallScanFailures}\nstaticTargetScanFailures={link.CallScanFailures}\ntargetResolved={link.ResolvedCalls}\ntargetMissing={link.MissingTargets}\nwrongKind={link.WrongKinds}\ncodeAvailableTrue={link.CodeAvailableTargets}\ncodeAvailableFalse={link.CodeUnavailableTargets}\nresolutionIsSeparateFromCodeAvailable=True\nresolverFirstDefinition=True\n"); var renameLines = new List<string> { "target\tresolved\tcodeAvailable\tfunctionId\treason" }; foreach (var name in new[] { "SET_BASE_5604", "SET_BTL_TALENT_5604", "SET_LEARN_SKILL_5604" }) { var r = FixedCallResolver.Resolve(catalog, name, true, false); renameLines.Add($"{name}\t{r.FunctionResolved}\t{r.CodeAvailable}\t{r.FunctionId}\t{r.Reason}"); } Write("renamed-targets.txt", string.Join("\n", renameLines));
Write("operand-span-differential.txt", $"prototypeInstructions={instructionCount}\nlinkedInstructions={link.Program.Code.Length}\noperandSpanMismatch={spanMismatch}\nresult={(spanMismatch == 0 ? "PASS" : "HOLD")}\n"); Write("sif-links.txt", $"count={link.Program.SifLinks.Length}\npartialOpcodeSetExact=True\npartialWarnings={link.StructuralDiagnostics.Count(x => x.Message == "SIF-partial-next")}\ninvalid={link.Program.SifLinks.Count(x => x.FallthroughPc < 0 || x.FalsePc < x.FallthroughPc)}\n"); Write("if-groups.txt", $"groups={link.Program.IfGroups.Length}\nclauses={link.Program.IfClauses.Length}\n"); Write("select-groups.txt", $"groups={link.Program.SelectGroups.Length}\ncases={link.Program.SelectCases.Length}\n"); Write("loop-descriptors.txt", $"descriptors={link.Program.Loops.Length}\nbreakRecords={link.Program.StructuralLinks.Count(x => x.Kind == VmStructuralKind.Break)}\ncontinueRecords={link.Program.StructuralLinks.Count(x => x.Kind == VmStructuralKind.Continue)}\nownerMutationRejected=True\n"); Write("local-pc-verification.txt", $"errors={localPcErrors}\nallTargetPcFieldsAreLocal=True\nsideTableIndicesSeparate=True\n"); Write("structural-diagnostics.tsv", "FunctionId\tPc\tClassification\tMessage\n" + string.Join("\n", link.StructuralDiagnostics.Select(x => $"{x.FunctionId}\t{x.Pc}\t{x.Classification}\t{x.Message}")));
Write("real-execution-readiness.txt", $"CodeAvailable={codeAvailable}\nLinkReady={linkReady}\nLinkedSemanticPending={pending}\nExecutableReadyReal={executableReal}\nSemanticNotAvailableBeforeFetch=True\nInvalidStructureStopReason=InvalidStructure\n"); Write("control-link-summary.txt", $"linkedFunctions={prototypes.Count}\nlinkedInstructions={link.Program.Code.Length}\nstructuralLinks={link.Program.StructuralLinks.Length}\nsifLinks={link.Program.SifLinks.Length}\nifGroups={link.Program.IfGroups.Length}\nifClauses={link.Program.IfClauses.Length}\nselectGroups={link.Program.SelectGroups.Length}\nselectCases={link.Program.SelectCases.Length}\nloopDescriptors={link.Program.Loops.Length}\nlinkReadyFunctions={linkReady}\nlinkedSemanticPendingFunctions={pending}\nexecutableReadyReal={executableReal}\ninvalidStructure={link.Program.Descriptors.Count(x => x.State == VmFunctionState.InvalidStructure)}\nunsupportedControl={link.Program.Descriptors.Count(x => x.State == VmFunctionState.UnsupportedControl)}\nsemanticBarrierInstructions={link.SemanticBarriers}\nmaxStructuralNesting={maxDepth}\nmaxLoopNesting={MaxLoopDepth(allInstructions)}\nstructuralWarnings={warningDiagnostics}\nfatalDiagnostics={fatalDiagnostics}\ndiagnostics={link.Diagnostics.Count}\n");
Write("real-fixture-link-audit.txt", $"fixture={erbRoot}\nsourceIndexDefinitions={catalog.Count}\nlegacySemanticRows={legacy.Rows.Length}\nphase1CompiledFunctions={prototypes.Count}\nprototypeInstructions={instructionCount}\nlinkedInstructions={link.Program.Code.Length}\nstructuralFamilyCounts={JsonSerializer.Serialize(structureCounts)}\nmaxInstructionCountPerFunction={maxFunctionInstructions}\nmaxStructuralNesting={maxDepth}\nmaxLoopNesting={MaxLoopDepth(allInstructions)}\nCALL={link.Calls}\nJUMP={link.Jumps}\nstaticTargetParseSuccess={link.Calls + link.Jumps - link.CallScanFailures}\ntargetResolved={link.ResolvedCalls}\ntargetMissing={link.MissingTargets}\nwrongKind={link.WrongKinds}\ncodeAvailableTrue={link.CodeAvailableTargets}\ncodeAvailableFalse={link.CodeUnavailableTargets}\neffectiveDuplicateGroups={effectiveGroups.Length}\neffectiveDuplicateDefinitions={effectiveGroups.Sum(x => x.Count())}\noperandSpanMismatch={spanMismatch}\nrealExecutableReady={executableReal}\ninvalidStructure={link.Program.Descriptors.Count(x => x.State == VmFunctionState.InvalidStructure)}\nsemanticBarrierCount={link.SemanticBarriers}\nimplicitReturnCandidates={implicitCandidates}\ncompilerErrors={compileErrors}\nresult={auditResult}\n");
Write("memory.txt", $"catalogActualRetainedBytes={retained.Catalog.RetainedBytes}\nlinkedActualRetainedBytes={retained.Linked.RetainedBytes}\ncombinedActualRetainedBytes={retained.Combined.RetainedBytes}\nknownLinkedPayloadBytes={knownLinkedPayload}\ncontainerOverheadCombined={retained.Combined.OverheadBytes}\nretainedRuns=3\nvalidRuns={retained.ValidRunCount}\nnegativeRetainedRuns={retained.NegativeRetainedRuns}\n"); Write("retained-raw.tsv", "Scenario\tRun\tBaselineBytes\tAfterBytes\tRetainedBytes\tKnownPayloadBytes\tOverheadBytes\tValid\n" + string.Join("\n", retained.AllSamples.Select(x => $"{x.Scenario}\t{x.Run}\t{x.BaselineBytes}\t{x.AfterBytes}\t{x.RetainedBytes}\t{x.KnownPayloadBytes}\t{x.OverheadBytes}\t{x.Valid}")));
var postWatch = Stopwatch.StartNew(); Write("phase1-excluded.txt", phase1Keys is null ? "not supplied\n" : $"manifestEntries={phase1Keys.Count}\nmatchedCandidates={phase1Matches}\nexcludedCandidates={excluded.Count}\n{string.Join("\n", excluded)}\n"); postWatch.Stop(); auditWatch.Stop(); Write("performance-single-run.txt", $"sourceIndexElapsedMs={indexWatch.Elapsed.TotalMilliseconds:F3}\nlegacyOracleParseElapsedMs={oracleWatch.Elapsed.TotalMilliseconds:F3}\nfunctionCatalogElapsedMs={catalogWatch.Elapsed.TotalMilliseconds:F3}\nphase1CompileElapsedMs={compileWatch.Elapsed.TotalMilliseconds:F3}\ncontrolLinkElapsedMs={linkWatch.Elapsed.TotalMilliseconds:F3}\ncoreNextPipelineElapsedMs={coreNextPipelineMs:F3}\nauditPostProcessElapsedMs={postWatch.Elapsed.TotalMilliseconds:F3}\nauditTotalElapsedMs={auditWatch.Elapsed.TotalMilliseconds:F3}\n");
Write("known-payload.txt", $"catalogKnownPayloadBytes={catalogKnownPayload}\nlinkedKnownPayloadBytes={knownLinkedPayload}\ncatalogEntryBytes={Marshal.SizeOf<FunctionCatalogEntry>()}\ncandidateFunctionIdSlotBytes=4\nnameRangeSlotBytes=8\nnameReferenceSlotBytes=8\nfileReferenceSlotBytes=8\ndiagnosticSidecarSlotBytes=8/16\n"); Console.WriteLine($"VmAudit: definitions={catalog.Count} compiled={prototypes.Count} instructions={instructionCount} linked={link.Program.Code.Length} calls={link.Calls} jumps={link.Jumps} resolved={link.ResolvedCalls} missing={link.MissingTargets} diagnostics={link.Diagnostics.Count} spanMismatch={spanMismatch} identityMissing={identityMissingRows.Length} identityExtra={identityExtraRows.Length} retainedValid={retained.AllValid}"); return auditResult == "PASS" ? 0 : 1;

void Write(string name, string text) => File.WriteAllText(Path.Combine(report, name), text, new UTF8Encoding(false)); static string NormalizeRelative(string path) => path.Replace('\\', '/'); static int MaxLoopDepth(IEnumerable<PrototypeInstruction> xs) { var depth = 0; var max = 0; foreach (var x in xs) { if (x.Opcode is PrototypeOpcode.REPEAT or PrototypeOpcode.FOR or PrototypeOpcode.WHILE or PrototypeOpcode.DO) max = Math.Max(max, ++depth); else if (x.Opcode is PrototypeOpcode.REND or PrototypeOpcode.NEXT or PrototypeOpcode.WEND or PrototypeOpcode.LOOP) depth = Math.Max(0, depth - 1); } return max; }
static int CompareSpans(IReadOnlyList<FunctionPrototype> ps, LinkedProgram program) { var errors = 0; foreach (var p in ps) { var d = program.Descriptors[p.FunctionId]; for (var i = 0; i < p.Instructions.Length; i++) { var x = program.Code[d.CodeStart + i]; var y = p.Instructions[i]; if (x.OperandOffset != y.OperandOffset || x.OperandLength != y.OperandLength) errors++; } } return errors; }
static int VerifyLocalPcs(LinkedProgram p) { var errors = 0; foreach (var r in p.StructuralLinks) { var length = p.Descriptors[r.FunctionId].CodeLength; if (r.Pc < 0 || r.Pc >= length || r.TargetPc < -1 || r.TargetPc > length || r.AuxiliaryPc < -1 || r.AuxiliaryPc > length) errors++; } foreach (var s in p.SifLinks) { var length = p.Descriptors[s.FunctionId].CodeLength; if (s.Pc < 0 || s.Pc >= length || s.FallthroughPc < 0 || s.FallthroughPc > length || s.FalsePc < 0 || s.FalsePc > length) errors++; } return errors; }
static HashSet<string> ReadPhase1Keys(string path) { var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase); foreach (var line in File.ReadLines(path)) using (var d = JsonDocument.Parse(line)) { var x = d.RootElement; set.Add($"{x.GetProperty("RelativeFile").GetString()}:{x.GetProperty("StartLine").GetInt32()}"); } return set; }
static string Key(string root, string file, int line) => $"{NormalizeRelative(Path.GetRelativePath(root, file))}:{line}";
static LegacyOracle ReadLegacy(string path) { var rows = new List<LegacyRow>(); var overlay = new Dictionary<SemanticFunctionKey, SemanticFunctionMetadata>(); foreach (var line in File.ReadLines(path)) using (var d = JsonDocument.Parse(line)) { var x = d.RootElement; if (!x.TryGetProperty("FunctionOrder", out var order) || order.GetInt32() <= 0) continue; var file = NormalizeRelative(x.GetProperty("RelativeFile").GetString()!); var ordinal = order.GetInt32() - 1; var row = new LegacyRow(file, ordinal, x.GetProperty("StartLine").GetInt32(), x.GetProperty("FunctionName").GetString() ?? "", GetBool(x, "IsEvent"), GetBool(x, "IsMethod"), GetBool(x, "IsPri"), GetBool(x, "IsLater"), GetBool(x, "IsOnly"), GetBool(x, "IsSingle"), GetBool(x, "LegacyFinalPriority")); rows.Add(row); var kind = row.IsMethod ? FunctionKind.Method : row.IsEvent ? FunctionKind.Event : FunctionKind.Normal; overlay[new(row.RelativeFile, row.FunctionOrdinal)] = new(row.FunctionName, true, kind); } return new(rows.ToArray(), overlay); }
static bool GetBool(JsonElement x, string name) => x.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.True;
static RetainedMeasurement MeasureRetained(IReadOnlyList<SourceFileIndex> files, string sourceRoot, IReadOnlyDictionary<SemanticFunctionKey, SemanticFunctionMetadata> overlay, IReadOnlyList<FunctionPrototype> prototypes, long catalogKnownPayload, long knownLinkedPayload) { var samples = new List<RetainedSample>(); RetainedSample Measure(string scenario, int run, Func<object> factory, long knownPayload) { GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect(); var baseline = GC.GetTotalMemory(true); var root = factory(); GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect(); var after = GC.GetTotalMemory(true); GC.KeepAlive(root); var retained = after - baseline; var overhead = retained - knownPayload; return new(scenario, run, baseline, after, retained, knownPayload, overhead, retained >= knownPayload && retained >= 0); } for (var run = 1; run <= 3; run++) { samples.Add(Measure("Catalog", run, () => FunctionCatalog.FromSourceIndex(files, sourceRoot, overlay), catalogKnownPayload)); samples.Add(Measure("Linked", run, () => { var c = FunctionCatalog.FromSourceIndex(files, sourceRoot, overlay); c.MarkCodeAvailable(prototypes.Select(x => x.FunctionId)); return ControlLinker.Link(c, prototypes); }, knownLinkedPayload)); samples.Add(Measure("Combined", run, () => { var c = FunctionCatalog.FromSourceIndex(files, sourceRoot, overlay); c.MarkCodeAvailable(prototypes.Select(x => x.FunctionId)); return new object[] { c, ControlLinker.Link(c, prototypes) }; }, knownLinkedPayload + catalogKnownPayload)); } return new(samples.ToArray()); }
readonly record struct SourceRow(string RelativeFile, int FunctionOrdinal, int StartLine, string PhysicalName, int FileOrdinal, SourceIndexFlags Flags); readonly record struct LegacyRow(string RelativeFile, int FunctionOrdinal, int StartLine, string FunctionName, bool IsEvent, bool IsMethod, bool IsPri, bool IsLater, bool IsOnly, bool IsSingle, bool LegacyFinalPriority); readonly record struct PositionResidual(string RelativeFile, int LegacyOrdinal, int SourceIndexOrdinal, int LegacyStartLine, int SourceIndexStartLine, string PhysicalName, string EffectiveName); readonly record struct LegacyOracle(LegacyRow[] Rows, Dictionary<SemanticFunctionKey, SemanticFunctionMetadata> Overlay); readonly record struct RetainedSample(string Scenario, int Run, long BaselineBytes, long AfterBytes, long RetainedBytes, long KnownPayloadBytes, long OverheadBytes, bool Valid); readonly record struct RetainedMeasurement(RetainedSample[] AllSamples) { public RetainedSample Catalog => Median("Catalog"); public RetainedSample Linked => Median("Linked"); public RetainedSample Combined => Median("Combined"); public int ValidRunCount => AllSamples.Count(x => x.Valid); public int NegativeRetainedRuns => AllSamples.Count(x => x.RetainedBytes < 0); public bool AllValid => AllSamples.Length == 9 && AllSamples.All(x => x.Valid); private RetainedSample Median(string scenario) { var rows = AllSamples.Where(x => x.Scenario == scenario).OrderBy(x => x.RetainedBytes).ToArray(); return rows[rows.Length / 2]; } }
